/** The grace days recorded for the grade in force on the date, as text; blank with none. */
graceShown(grade: string, date: string | null): string {
  return valueOn(this.dated(), `grace-${grade}`, date) ?? '';
}

/** The proof threshold recorded for the grade in force on the date, as text; blank with none. */
proofThresholdShown(grade: string, date: string | null): string {
  return valueOn(this.dated(), `proof-threshold-${grade}`, date) ?? '';
}

async setPolicyDate(sheet: string, value: string | null): Promise<void> {
  const s = await firstValueFrom(
    this.http.put<SettingsView>(`/api/sheets/${encodeURIComponent(sheet)}/settings/policy-date`, { value }),
      <label for="setting-grace-days">Grace days (open periods this many days past their end close when today moves; blank for off)</label>
      <input
        id="setting-grace-days"
        data-testid="setting-grace-days"
        inputmode="numeric"
        [value]="graceDays()"
        (input)="graceDays.set(value($event)); graceDaysChanged = true; settingsError.set(null)"
        (keydown.delete)="graceDaysChanged = true; settingsError.set(null)"
        (keydown.backspace)="graceDaysChanged = true; settingsError.set(null)"
      />
      <label for="setting-escalate-after">Escalate after (reminding a claim at least this many days after its last reminder escalates it; blank for off)</label>
      <input
        id="setting-escalate-after"
        data-testid="setting-escalate-after"
        inputmode="numeric"
        [value]="escalateAfter()"
        (input)="escalateAfter.set(value($event)); escalateAfterChanged = true; settingsError.set(null)"
        (keydown.delete)="escalateAfterChanged = true; settingsError.set(null)"
        (keydown.backspace)="escalateAfterChanged = true; settingsError.set(null)"
      />
      <label for="setting-review-sla">Review SLA (a REVIEW claim this many days past the day it went to review is late; blank for none)</label>
      <input
        id="setting-review-sla"
        data-testid="setting-review-sla"
        inputmode="numeric"
        [value]="reviewSla()"
        (input)="reviewSla.set(value($event)); reviewSlaChanged = true; settingsError.set(null)"
        (keydown.delete)="reviewSlaChanged = true; settingsError.set(null)"
        (keydown.backspace)="reviewSlaChanged = true; settingsError.set(null)"
      />
      <label for="setting-proof-kinds">Proof kinds (receipt, photo, comma separated: a claim above its proof threshold needs a proof of each; blank for none)</label>
      <input
        id="setting-proof-kinds"
        data-testid="setting-proof-kinds"
        [value]="proofKinds()"
        (input)="proofKinds.set(value($event)); proofKindsChanged = true; settingsError.set(null)"
        (keydown.delete)="proofKindsChanged = true; settingsError.set(null)"
        (keydown.backspace)="proofKindsChanged = true; settingsError.set(null)"
      />
      <label for="setting-default-grade">Default grade (A, B or C: the grade the quick-add bar and an import line with a blank grade give a new person; blank for A)</label>
      <input
      />
      @for (g of grades; track g) {
        <label [for]="'setting-proof-threshold-' + g">Proof threshold for grade {{ g }} (in place of the sheet's; blank for none)</label>
        <input
          [id]="'setting-proof-threshold-' + g"
          [attr.data-testid]="'setting-proof-threshold-' + g"
          inputmode="decimal"
          [value]="gradeProof()[g] ?? ''"
          (input)="setGradeProofField(g, value($event))"
          (keydown.delete)="gradeProofChanged.add(g); settingsError.set(null)"
          (keydown.backspace)="gradeProofChanged.add(g); settingsError.set(null)"
        />
        <label [for]="'setting-proof-threshold-' + g + '-from'">Proof threshold for grade {{ g }} from (blank for the sheet's today)</label>
        <input
          [id]="'setting-proof-threshold-' + g + '-from'"
          [attr.data-testid]="'setting-proof-threshold-' + g + '-from'"
          type="date"
          [value]="from()[proofKey(g)] ?? ''"
          (input)="setFrom(proofKey(g), value($event))"
          (change)="setFrom(proofKey(g), value($event))"
        />
      }
      <label for="setting-note-threshold">Note threshold (a claim due above it needs a note to open; blank for none)</label>
      <input
        id="setting-note-threshold"
        data-testid="setting-note-threshold"
        inputmode="decimal"
      </fieldset>
      <button type="submit" data-testid="settings-save">Save settings</button>
      @if (settingsError(); as err) {
        <p role="alert" data-testid="settings-error">{{ err | fig }}</p>
      }
    </form>
    <p>Clerk limit in force: <strong data-testid="setting-clerk-limit-current">{{ (store.clerkLimit() ?? '') | fig }}</strong></p>
    <p>Floor in force: <strong data-testid="setting-floor-current">{{ store.floorToday() | fig }}</strong></p>
    <p>Terms in force: <strong data-testid="setting-terms-current">{{ store.termsToday() | fig }}</strong> days</p>
    @for (g of grades; track g) {
      <p>
        Terms in force for grade {{ g }}:
        <strong [attr.data-testid]="'setting-terms-' + g + '-current'">{{ (store.termsFor(g, session.sheetToday())) | fig }}</strong> days
      </p>
    }
    @for (g of grades; track g) {
      <p>
        Grace days in force for grade {{ g }}:
        <strong [attr.data-testid]="'setting-grace-' + g + '-current'">{{ (store.graceShown(g, session.sheetToday())) | fig }}</strong>
      </p>
    }
    <p>Late percent in force: <strong data-testid="setting-late-pct-current">{{ store.latePctToday() | fig }}</strong></p>
    <p>Policy date in force: <strong data-testid="setting-policy-date-current">{{ (store.policyDate() ?? '') | fig }}</strong></p>
    <p>
